package com.realstant.nativegame; import java.util.*; public final class WeatherParticles { public final List<Particle> active=new ArrayList<>(); public void spawn(int n,float x,float y,float z){for(int i=0;i<n;i++){Particle p=new Particle();p.x=x+(float)Math.random()*20-10;p.y=y+(float)Math.random()*8;p.z=z+(float)Math.random()*20-10;p.vy=-3;p.life=3;active.add(p);}} public void update(float dt){for(Iterator<Particle>it=active.iterator();it.hasNext();){Particle p=it.next();p.update(dt);if(p.life<=0)it.remove();}} }
